mapper.select:
SELECT a.taskCount AS taskCount, IFNULL(b.oppoCount, 0) AS oppoCount FROM ( SELECT COUNT(task.id_) AS taskCount FROM tcomm_task task LEFT JOIN topp_opportunity oppo ON task.info_id = oppo.id_ WHERE
) a, ( SELECT COUNT(c.infoId) AS oppoCount FROM ( SELECT task.info_id AS infoId FROM tcomm_task task LEFT JOIN topp_opportunity oppo ON task.info_id = oppo.id_ WHERE
GROUP BY task.info_id ) c ) b
